// The agent sends { incident_id, input: { query } }. Work out what kind of
// indicator it is so downstream nodes can route to the right provider.
const body = $input.first().json.body ?? $input.first().json;
const query = String(body?.input?.query ?? '').trim();

const patterns = {
  ipv4: /^(?:(?:25[0-5]|2[0-4]\d|1?\d?\d)\.){3}(?:25[0-5]|2[0-4]\d|1?\d?\d)$/,
  sha256: /^[a-fA-F0-9]{64}$/,
  md5: /^[a-fA-F0-9]{32}$/,
  domain: /^(?:[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?\.)+[a-zA-Z]{2,}$/,
  email: /^[^@\s]+@[^@\s]+\.[^@\s]+$/,
};

let kind = 'unknown';
for (const [name, re] of Object.entries(patterns)) {
  if (re.test(query)) { kind = name; break; }
}

return [{
  json: {
    incident_id: body.incident_id ?? '',
    query,
    kind,
    demo: String($env.AGENTICIR_DEMO_INTEL ?? '').toLowerCase() === 'true',
  },
}];

// ── DEMO FIXTURES ──────────────────────────────────────────────────────
// Deterministic, plausible intel for the demo scenarios. Every response
// carries demo_fixture:true so nothing downstream can mistake it for a
// real provider verdict.
const { query, kind, incident_id } = $input.first().json;
const key = query.toLowerCase();

const FIXTURES = {
  'cdn-update-service.top': {
    verdict: 'malicious',
    confidence: 0.93,
    categories: ['command-and-control', 'malware-distribution'],
    first_seen: '2026-07-29',
    registrar: 'Privacy-protected (NiceNIC)',
    domain_age_days: 11,
    associated_families: ['Latrodectus'],
    providers: [
      { name: 'demo-intel', verdict: 'malicious', detections: '14/71' },
      { name: 'demo-passive-dns', verdict: 'suspicious', note: 'Resolved to 5 distinct hosts in 11 days' }
    ],
    summary: 'Newly registered domain serving as C2 for a Latrodectus loader campaign. Beacon interval ~60s over HTTPS.'
  },
  '45.33.32.156': {
    verdict: 'suspicious',
    confidence: 0.71,
    categories: ['scanning', 'brute-force'],
    asn: 'AS63949 Akamai Connected Cloud',
    country: 'US',
    first_seen: '2026-08-01',
    providers: [
      { name: 'demo-intel', verdict: 'suspicious', detections: '4/71' },
      { name: 'demo-scanner-feed', verdict: 'benign', note: 'Matches a known internet-wide research scanner' }
    ],
    summary: 'Providers disagree: flagged for credential stuffing by one feed, classified as benign research scanning by another. Treat as unresolved.'
  },
  '9f2b8c1e4a7d3f6b0c5e8a1d4f7b2c9e6a3d0f5b8c1e4a7d2f9b6c3e0a5d8f1b': {
    verdict: 'malicious',
    confidence: 0.88,
    file_type: 'PE32 executable',
    first_submission: '2026-08-02',
    signed: false,
    associated_families: ['Latrodectus'],
    providers: [{ name: 'demo-intel', verdict: 'malicious', detections: '46/72' }],
    summary: 'Loader binary matching the Latrodectus family. Establishes persistence via a scheduled task.'
  },
  'mail.corp-partner-portal.com': {
    verdict: 'benign',
    confidence: 0.9,
    categories: ['business'],
    domain_age_days: 2190,
    providers: [{ name: 'demo-intel', verdict: 'clean', detections: '0/71' }],
    summary: 'Established supplier domain, six years old, clean across all feeds. No indication of compromise.'
  },
};

const hit = FIXTURES[key];

return [{
  json: hit
    ? { indicator: query, kind, incident_id, demo_fixture: true, ...hit }
    : {
        indicator: query,
        kind,
        incident_id,
        demo_fixture: true,
        verdict: 'unknown',
        confidence: 0.0,
        providers: [],
        summary: 'No demo fixture exists for this indicator. Treat it as UNKNOWN — '
               + 'this is an absence of data, not evidence that it is benign.',
      },
}];

// ── LIVE LOOKUP ────────────────────────────────────────────────────────
// Wire HTTP Request nodes to the feeds you license (VirusTotal, GreyNoise,
// AbuseIPDB, Shodan, MISP, internal CMDB) and merge their verdicts here.
//
// Returning an explicit "not_checked" matters: the enrichment agent is told
// to distinguish unknown from benign, and a fabricated clean verdict would
// quietly suppress a real detection.
const { query, kind, incident_id } = $input.first().json;

return [{
  json: {
    indicator: query,
    kind,
    incident_id,
    verdict: 'not_checked',
    providers: [],
    note: 'No threat-intel provider is configured in this n8n workflow yet. '
        + 'Treat this indicator as UNKNOWN, not benign.',
  },
}];
